U=struct.Struct('<I');P=struct.Struct('<II');T=struct.Struct('<III')
def write(p,data):p.write_bytes(data);return {'path':str(p),'sha256':hashlib.sha256(data).hexdigest()}
def js(p,x):return write(p,(json.dumps(x,sort_keys=True)+'\n').encode())
def binfile(p,fmt,x):return write(p,b''.join(fmt.pack(*v) if isinstance(v,tuple) else fmt.pack(v) for v in x))
