  dummy=js(b/'dummy',{});req={'snapshot':sp,**self.stream,'grid':report['grid'],'component_manifest':dummy,'component_source':dummy,'source_files':[],'resolver_sha256':'','adapter_sha256':'','named_identity_sha256':'','identity_watch_sha256':''};request=js(b/'request.json',req)
