 def runv(self):
  js(self.cfgpath,self.cfg)
  class Validator:
   @staticmethod
   def validate(*a):return {'status':'diagnostic-candidate-bound'}
  class Resolver:
   def resolve(s,r):return self.point
   def lineage_specs(s,m):return []
  class PointValidator:
   @staticmethod
   def claims_for(*args):return {}
  def module(name,path):return Validator if name=='stage2_candidate_validator' else (PointValidator if name=='reviewed_point_claim_validator' else Resolver())
  with patch.object(driver,'loadmodule',side_effect=module),patch.object(driver.polygon_resolution,'resolve',return_value=self.poly):return driver.run(self.cfgpath)
 def test_mixed_driver_writes_expected(self):
  self.runv();r=json.loads((self.b/'out/report.json').read_text());self.assertEqual(r['writer']['changed_cells'],6);self.assertEqual(set(r['writer']['affiliation_statistics']),{'point','poly'});self.assertEqual(r['writer']['polygon_root_statistics']['poly']['11'],{'applied_cells':3,'changed_cells':3});self.assertEqual(r['polygon_component_extents']['poly']['11']['per_feature'][0]['outside_cells'],1)
 def test_evidence_source_is_authenticated_and_traced(self):
  article=self.src/'article.xml';article.write_bytes(b'Raw scholarly article');sha=hashlib.sha256(article.read_bytes()).hexdigest();pin={'source_id':'article','version':'v1','sha256':sha,'size_bytes':article.stat().st_size,'r2_bucket':'bucket','r2_key':'article'}
  reqpath=Path(self.cfg['point_request']['path']);req=json.loads(reqpath.read_text());sp=Path(req['snapshot']['path']);snap=json.loads(sp.read_text());snap['sources'].append(pin);snap['source_lineage_assets'].append({**pin,'kind':'raw','provenance':{'representation':'provider_original'},'source_uri':'https://example.org','provider':'Journal','attribution':'Author','license_name':'CC BY','license_uri':'https://example.org/license'});snap['list1_entry_evidence_sources']=[{'decision_revision':'r','entry_id':'ep','role':'geographic_membership_evidence','source_id':'article','source_version':'v1','citation_section':'Study area','interpretation':'Selected membership','limitations':['Human-reviewed, not proof']}];req['snapshot']=js(sp,snap);self.point['snapshot_sha256']=req['snapshot']['sha256'];self.cfg['point_request']=js(reqpath,req);self.cfg['evidence_source_files']=[{**pin,'path':str(article)}]
  self.runv();r=json.loads((self.b/'out/report.json').read_text());e=r['policy']['entries']['ep']['geographic_membership_evidence'][0];self.assertEqual(e['interpretation_status'],'selected_interpretation');self.assertEqual(e['source_sha256'],sha);self.assertEqual(e['citation_section'],'Study area')
