  assertion={'kind':'selected_assertion_not_recomputed','proof_sha256':'a'*64};self.poly['claims'][0]['exclusion_witness_assertion']=assertion
  self.runv();r=json.loads((self.b/'out/report.json').read_text());self.assertEqual(r['polygon_resolution']['claims'][0]['exclusion_witness_assertion'],assertion)
